<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\{PortalController as P,AdminController as A};
Route::get('/',[P::class,'home']);Route::redirect('/index.html','/',301);Route::redirect('/submit.html','/submit',301);Route::view('/submit','submit');Route::post('/submit',[P::class,'submit'])->middleware('throttle:5,10');Route::get('/opportunities/{type}',[P::class,'index']);Route::get('/entry/{slug}',[P::class,'show']);Route::get('/sitemap.xml',[P::class,'sitemap']);Route::get('/robots.txt',fn()=>response("User-agent: *\nDisallow: /admin\nSitemap: ".url('/sitemap.xml')."\n",200,['Content-Type'=>'text/plain']));
Route::view('/admin/login','login')->name('login');Route::post('/admin/login',[A::class,'login'])->middleware('throttle:5,1');
Route::middleware(['auth',\App\Http\Middleware\AdminOnly::class])->prefix('admin')->group(function(){Route::get('/',[A::class,'dashboard']);Route::get('/content/{type}',[A::class,'content']);Route::get('/sources',[A::class,'sources']);Route::get('/submissions',[A::class,'submissions']);Route::get('/imports',[A::class,'imports']);Route::get('/categories',[\App\Http\Controllers\NavigationController::class,'categories']);Route::post('/categories/{category?}',[\App\Http\Controllers\NavigationController::class,'category']);Route::get('/menus',[\App\Http\Controllers\NavigationController::class,'menus']);Route::post('/menus/{menu?}',[\App\Http\Controllers\NavigationController::class,'menu']);Route::delete('/menus/{menu}',[\App\Http\Controllers\NavigationController::class,'remove']);Route::post('/logout',[A::class,'logout']);Route::post('/entries',[A::class,'entry']);Route::get('/entries/{entry}',fn(\App\Models\Entry $entry)=>view('edit',['entry'=>$entry]));Route::post('/entries/{entry}',[A::class,'entry']);Route::get('/activity',[A::class,'activity']);Route::post('/entries/{entry}/status',[A::class,'status']);Route::post('/entries/{entry}/verify',[A::class,'verify']);Route::post('/sources',[A::class,'source']);Route::post('/sources/{source}',[A::class,'source']);Route::post('/submissions/{submission}',[A::class,'submission']);});
Route::get('/scholarship-sources',fn()=>redirect('/categories/scholarship-providers',301));
Route::get('/directory.html',fn(\Illuminate\Http\Request $r)=>redirect('/opportunities/directory'.($r->filled('q')?'?'.http_build_query(['q'=>(string)$r->input('q')]):''),301));
Route::get('/ads.txt',function(){ $id=config('advertising.publisher');abort_unless(preg_match('/^pub-[0-9]{16}$/D',$id),404);return response('google.com, '.$id.', DIRECT, f08c47fec0942fa0'.PHP_EOL,200,['Content-Type'=>'text/plain']);});
Route::get('/profile-{slug}.html',fn(string $slug)=>redirect('/entry/'.$slug,301))->where('slug','[a-z0-9-]+');
Route::get('/listing.html',function(\Illuminate\Http\Request $r){$id=$r->input('id');return redirect(is_string($id)&&preg_match('/^[a-z0-9-]+$/D',$id)?'/entry/'.$id:'/opportunities/directory',301);});
Route::get('/categories',[P::class,'categories']);
Route::get('/categories/{slug}',[P::class,'category']);
Route::get('/{page}.html',[P::class,'legacy'])->where('page','[a-z0-9-]+');
